{
  "originalFormula": "V_{bi} = 0.0259 \ln \\left( \\frac{N_{D}}{N_{A}} \\right)",
  "genericFormula": "V_{bi} = k \ln \\left( \\frac{N_{D}}{N_{A}} \\right)",
  "description": "Esta fórmula representa a tensão de built-in (ou tensão de junção) em um diodo semicondutor, que é a tensão que se estabelece na junção entre dois tipos de dopagem de semicondutores, um tipo n (dopado com átomos que têm elétrons extras) e um tipo p (dopado com átomos que têm lacunas ou falta de elétrons). Essa tensão é crucial para entender o funcionamento de dispositivos semicondutores como diodos e transistores.",
  "concepts": [
    "Tensão de built-in",
    "Dopagem de semicondutores",
    "Juncão p-n",
    "Equilíbrio de cargas"
  ],
  "symbols": [
    {
      "symbol": "V_{bi}",
      "description": "Representa a tensão de built-in, que é a diferença de potencial elétrico na junção de um diodo semicondutor."
    },
    {
      "symbol": "N_{D}",
      "description": "Representa a concentração de dopantes do tipo n, que são átomos que fornecem elétrons extras ao semicondutor."
    },
    {
      "symbol": "N_{A}",
      "description": "Representa a concentração de dopantes do tipo p, que são átomos que criam lacunas ou faltas de elétrons no semicondutor."
    },
    {
      "symbol": "k",
      "description": "Representa uma constante que está relacionada à temperatura e à natureza do material semicondutor, que neste caso é aproximadamente 0.0259 volts a temperatura ambiente."
    },
    {
      "symbol": "ln",
      "description": "Representa a função logarítmica natural, que é usada para calcular o logaritmo de um número em base e, onde e é a base dos logaritmos naturais."
    }
  ]
}

{
  "originalFormula": "J_{p}(x_n) = 0.1064 \, \\text{A/cm}^{2}",
  "genericFormula": "J_{p}(x_n) = J_{p}",
  "description": "Esta fórmula representa a densidade de corrente de portadores de carga positiva (buracos) em um semicondutor em uma determinada posição, que é indicada por x_n. A densidade de corrente é uma medida de quanta corrente elétrica flui através de uma unidade de área.",
  "concepts": [
    "Densidade de corrente",
    "Portadores de carga",
    "Semicondutores"
  ],
  "symbols": [
    {
      "symbol": "J_{p}",
      "description": "Representa a densidade de corrente dos portadores de carga positiva, que são os buracos em um semicondutor."
    },
    {
      "symbol": "x_n",
      "description": "Indica a posição no material semicondutor onde a densidade de corrente está sendo avaliada."
    }
  ]
}

{
  "originalFormula": "J_{n}(-x_p) = 0.00774 \, \\text{A/cm}^{2}",
  "genericFormula": "J_{n}(-x_p) = I \, \\text{A/cm}^{2}",
  "description": "Esta fórmula representa a densidade de corrente de portadores de carga negativa (elétrons) em um ponto específico de um material semicondutor, onde a densidade de corrente é medida em amperes por centímetro quadrado. O valor numérico específico indica a quantidade de corrente que flui por unidade de área.",
  "concepts": [
    "Densidade de corrente",
    "Semicondutores",
    "Portadores de carga",
    "Elétrons"
  ],
  "symbols": [
    {
      "symbol": "J_{n}(-x_p)",
      "description": "Representa a densidade de corrente de portadores de carga negativa (elétrons) em uma posição específica, indicada por -x_p, dentro do material semicondutor."
    },
    {
      "symbol": "I",
      "description": "Representa a densidade de corrente em amperes por centímetro quadrado, que é uma medida da quantidade de corrente elétrica que flui através de uma área específica."
    },
    {
      "symbol": "-x_p",
      "description": "Indica a posição no material semicondutor onde a densidade de corrente está sendo medida, sendo que o sinal negativo pode denotar uma direção específica no contexto do problema."
    }
  ]
}
